import 'package:cephalopod/core/board/models/side_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'dice_tally_ui.freezed.dart';

/// How many dice each side has on the board, as the screen shows it: Player
/// 1's side, with the coral dice, then Player 2's, with the cream ones.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class DiceTallyUi with _$DiceTallyUi {
  const factory DiceTallyUi({
    required SideTallyUi playerOne,
    required SideTallyUi playerTwo,
  }) = _DiceTallyUi;
}

/// One side's count: who the [side] is, how many [dice] it has on the
/// board, and whether it is the side to move ([toMove]). Neither side is to
/// move once the game is over.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class SideTallyUi with _$SideTallyUi {
  const factory SideTallyUi({
    required SideUi side,
    required int dice,
    required bool toMove,
  }) = _SideTallyUi;
}
